import 'dart:io';
import 'dart:typed_data';

import 'package:flutter/material.dart' show DateTimeRange;
import 'package:path_provider/path_provider.dart';
import 'package:printing/printing.dart';

import 'package:inventory_management/data/api_service.dart';

/// Exports a report as a PDF generated by the API, then saves and shares it.
///
/// Report index (same order as the tabs in ReportsScreen):
/// 0 = Stock Summary, 1 = Stock In, 2 = Stock Out, 3 = Low Stock, 4 = Transactions
class ReportPdfService {
  ReportPdfService._();

  /// Downloads the PDF for [reportIndex] and [range], saves it on the device
  /// and opens the share sheet. Returns the path of the saved file.
  static Future<String> exportPdf({
    required int reportIndex,
    required DateTimeRange range,
  }) async {
    final api = ApiService();
    final DownloadedFile file;

    switch (reportIndex) {
      case 1:
        file = await api.exportStockTransactionReport(
          type: 'STOCK_IN',
          fromDate: range.start,
          toDate: range.end,
        );
        break;
      case 2:
        file = await api.exportStockTransactionReport(
          type: 'STOCK_OUT',
          fromDate: range.start,
          toDate: range.end,
        );
        break;
      case 4:
        file = await api.exportStockTransactionReport(
          fromDate: range.start,
          toDate: range.end,
        );
        break;
      case 3:
        file = await api.exportInventoryReport(
          lowStockOnly: true,
          fromDate: range.start,
          toDate: range.end,
        );
        break;
      default:
        file = await api.exportInventoryReport(
          fromDate: range.start,
          toDate: range.end,
        );
    }

    return _saveAndShare(file);
  }

  /// Saves the file first (so it still works when no app can handle sharing,
  /// e.g. on an emulator), then tries the share sheet.
  static Future<String> _saveAndShare(DownloadedFile file) async {
    final name = file.fileName.toLowerCase().endsWith('.pdf')
        ? file.fileName
        : '${file.fileName}.pdf';
    final bytes = Uint8List.fromList(file.bytes);

    Directory dir;
    try {
      dir = (await getExternalStorageDirectory()) ??
          await getApplicationDocumentsDirectory();
    } catch (_) {
      dir = await getApplicationDocumentsDirectory();
    }
    final saved = File('${dir.path}${Platform.pathSeparator}$name');
    await saved.writeAsBytes(bytes, flush: true);

    try {
      await Printing.sharePdf(bytes: bytes, filename: name);
    } catch (_) {}

    return saved.path;
  }
}
